import java.sql.*;import java.util.*;
class Task09Fix01SettlementProbe {public static void main(String[] a)throws Exception{try(var c=DriverManager.getConnection(System.getenv("AMA_TEST_DATABASE_URL"),System.getenv("AMA_TEST_DATABASE_USERNAME"),System.getenv("AMA_TEST_DATABASE_PASSWORD"))){var q=c.prepareStatement("SELECT t.id task_id,t.state task_state,e.id execution_id,e.operation_id,e.state execution_state,o.state operation_state,r.id reservation_id,r.settled_at,(SELECT COUNT(*) FROM generation_candidate g WHERE g.task_id=t.id) candidates,(SELECT COUNT(*) FROM model_reservation allr WHERE allr.id<=r.id) reservation_scan_rank,(SELECT COUNT(*) FROM model_reservation) reservation_total FROM durable_task t JOIN external_execution e ON e.task_id=t.id JOIN external_operation o ON o.id=e.operation_id JOIN model_reservation r ON r.execution_id=e.id WHERE t.id=? AND e.id=?");q.setString(1,"fa172992-cbf0-4527-a638-ab6e4853b819");q.setString(2,"3ea4befa-a586-4170-aa2c-5923fd678ae4");var rows=new ArrayList<Map<String,Object>>();try(var r=q.executeQuery()){while(r.next()){var m=new TreeMap<String,Object>();for(int i=1;i<=r.getMetaData().getColumnCount();i++){Object v=r.getObject(i);m.put(r.getMetaData().getColumnLabel(i),v==null?null:v.toString());}rows.add(m);}}System.out.println(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(rows));}}}
